import json

with open('/app/resources/treasury_bulletin_1990_09.json', 'r') as f:
    data = json.load(f)

elements = data.get('document', {}).get('elements', [])

# Get all figures and see which page they are on
figures = [e for e in elements if e.get('type') == 'figure']
print(f"Total figures: {len(figures)}")

# Check page distribution for all figures
page_counts = {}
for elem in elements:
    if 'bbox' in elem and elem['bbox']:
        bbox = elem['bbox'][0]
        page_id = bbox.get('page_id')
        if page_id not in page_counts:
            page_counts[page_id] = {'total': 0, 'figures': 0}
        page_counts[page_id]['total'] += 1
        if elem.get('type') == 'figure':
            page_counts[page_id]['figures'] += 1

print("\nPage distribution:")
for page_id in sorted(page_counts.keys()):
    print(f"  Page {page_id}: {page_counts[page_id]['total']} elements, {page_counts[page_id]['figures']} figures")
